#include <vector>
#include <string>
#include <unordered_map>

class Solution {
public:
    std::vector<std::string> getFolderNames(std::vector<std::string>& names) {
        std::unordered_map<std::string, int> used;
        std::vector<std::string> ans;
        ans.reserve(names.size());
        for (const auto& name : names) {
            if (!used.count(name)) {
                used[name] = 1;
                ans.push_back(name);
            } else {
                int k = used[name];
                std::string cand = name + "(" + std::to_string(k) + ")";
                while (used.count(cand)) {
                    k++;
                    cand = name + "(" + std::to_string(k) + ")";
                }
                used[name] = k + 1;
                used[cand] = 1;
                ans.push_back(cand);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public String[] getFolderNames(String[] names) {
        Map<String, Integer> used = new HashMap<>();
        String[] ans = new String[names.length];
        for (int i = 0; i < names.length; i++) {
            String name = names[i];
            if (!used.containsKey(name)) {
                used.put(name, 1);
                ans[i] = name;
            } else {
                int k = used.get(name);
                String cand = name + "(" + k + ")";
                while (used.containsKey(cand)) {
                    k++;
                    cand = name + "(" + k + ")";
                }
                used.put(name, k + 1);
                used.put(cand, 1);
                ans[i] = cand;
            }
        }
        return ans;
    }
}

var getFolderNames = function(names) {
    const used = new Map();
    const ans = [];
    for (const name of names) {
        if (!used.has(name)) {
            used.set(name, 1);
            ans.push(name);
        } else {
            let k = used.get(name);
            let cand = `${name}(${k})`;
            while (used.has(cand)) {
                k++;
                cand = `${name}(${k})`;
            }
            used.set(name, k + 1);
            used.set(cand, 1);
            ans.push(cand);
        }
    }
